import { tags } from "typia";

/**
 * Aggregated payment funnel statistics for a single scope (either overall or
 * for a specific segment) on the shoppingMall platform.
 *
 * Represents counts and monetary totals at key funnel stages, together with
 * conversion rates between sequential stages. All metrics are aggregated and do
 * not reveal individual customer or transaction details.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallPaymentFunnelAnalyticsItem = {
  /**
   * Number of orders created within the analytics scope.
   *
   * This is typically the first stage of the payment funnel, representing the
   * universe of orders that could potentially lead to payment attempts.
   */
  ordersCreatedCount: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of payment transactions initiated within the analytics scope.
   *
   * Includes initial payment attempts linked to in-scope orders, regardless
   * of whether they were subsequently authorized, captured, refunded, or
   * charged back.
   */
  paymentsInitiatedCount: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of payment authorizations that were successfully approved within
   * the analytics scope.
   *
   * This stage reflects the subset of initiated payments that passed initial
   * authorization checks by the payment provider or issuer.
   */
  authorizationsApprovedCount: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of payment captures that were successfully completed within the
   * analytics scope.
   *
   * Represents the subset of approved authorizations where funds were
   * actually captured and booked.
   */
  capturesCompletedCount: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of refund transactions processed within the analytics scope.
   *
   * This includes both full and partial refunds associated with captured
   * payments that fall into the time window and filter criteria.
   */
  refundsProcessedCount: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of payment chargebacks recorded within the analytics scope.
   *
   * Represents disputes or reversals initiated through financial institutions
   * against previously captured payments.
   */
  chargebacksRecordedCount: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Total monetary amount of orders created within the analytics scope.
   *
   * Expressed in the reporting currency chosen by the backend for this
   * analytics response. Typically represents the sum of order grand totals
   * before payment fees and external adjustments.
   */
  ordersTotalAmount: number & tags.Minimum<0>;

  /**
   * Total monetary amount of payment authorizations that were approved within
   * the analytics scope.
   *
   * Represents the volume of funds for which authorization succeeded, even if
   * later captures, refunds, or chargebacks changed the net settled amount.
   */
  authorizedTotalAmount: number & tags.Minimum<0>;

  /**
   * Total monetary amount of captures completed within the analytics scope.
   *
   * Represents the volume of funds actually captured and booked for in-scope
   * payments.
   */
  capturedTotalAmount: number & tags.Minimum<0>;

  /**
   * Total monetary amount refunded within the analytics scope.
   *
   * Includes both full and partial refunds associated with in-scope payments
   * and orders, expressed in the reporting currency.
   */
  refundedTotalAmount: number & tags.Minimum<0>;

  /**
   * Total monetary amount of chargebacks recorded within the analytics scope.
   *
   * Represents the volume of disputed funds that have been charged back by
   * financial institutions.
   */
  chargebackTotalAmount: number & tags.Minimum<0>;

  /**
   * Conversion rate from orders created to payments initiated.
   *
   * Computed as `paymentsInitiatedCount / max(1, ordersCreatedCount)` and
   * expressed as a value between 0 and 1. Represents how effectively created
   * orders progress to payment attempts.
   */
  orderToPaymentConversionRate: number & tags.Minimum<0> & tags.Maximum<1>;

  /**
   * Conversion rate from payments initiated to authorizations approved.
   *
   * Computed as `authorizationsApprovedCount / max(1,
   * paymentsInitiatedCount)` and expressed as a value between 0 and 1.
   * Highlights authorization success rates and potential issues with fraud or
   * issuer decline rates.
   */
  paymentToAuthorizationConversionRate: number &
    tags.Minimum<0> &
    tags.Maximum<1>;

  /**
   * Conversion rate from authorizations approved to captures completed.
   *
   * Computed as `capturesCompletedCount / max(1,
   * authorizationsApprovedCount)` and expressed as a value between 0 and 1.
   * Indicates to what extent successful authorizations lead to actual fund
   * capture.
   */
  authorizationToCaptureConversionRate: number &
    tags.Minimum<0> &
    tags.Maximum<1>;

  /**
   * Net captured amount after subtracting refunds and chargebacks from
   * captured volume within the analytics scope.
   *
   * Computed as `capturedTotalAmount - refundedTotalAmount -
   * chargebackTotalAmount`, truncated at zero if negative. Provides a summary
   * indicator of effective net revenue for the analyzed funnel slice.
   */
  netCapturedAmount: number & tags.Minimum<0>;
};
